import{_ as e,o as t,c as r,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const d=JSON.parse('{"title":"约翰·麦克法兰","description":"","frontmatter":{"title":"约翰·麦克法兰","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/约翰·麦克法兰.md","filePath":"04_people/约翰·麦克法兰.md"}'),o={name:"04_people/约翰·麦克法兰.md"};function n(i,a,s,_,h,c){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="约翰·麦克法兰-john-mcfarlane" tabindex="-1">约翰·麦克法兰（John McFarlane） <a class="header-anchor" href="#约翰·麦克法兰-john-mcfarlane" aria-label="Permalink to &quot;约翰·麦克法兰（John McFarlane）&quot;">​</a></h1><ul><li><strong>角色职位</strong>：所罗门兄弟高管</li><li><strong>与巴菲特关系</strong>：所罗门兄弟危机期间及重建阶段的公司管理层</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>约翰·麦克法兰是所罗门兄弟公司的高管，在公司历史上最为动荡的时期之一担任管理职务。1991年，所罗门兄弟因交易员约翰·梅里韦瑟违规炒作美国国债而爆发丑闻，这是华尔街有史以来最严重的金融丑闻之一。公司被禁止参与美国国债一级市场交易，面临前所未有的生存危机，市场信誉跌至谷底。</p><p>巴菲特在危机爆发后紧急注资并亲自介入公司管理，展现出非凡的危机处理能力。麦克法兰作为公司高管团队的重要成员，参与了危机期间的关键决策，与巴菲特及管理层其他成员共同制定应对方案。他参与了与财政部、美联储等监管机构的艰难谈判过程，为公司争取生存空间。</p><p>在危机化解后，麦克法兰参与了所罗门兄弟漫长的重建与整合过程。公司逐步恢复业务，并最终于1997年被巴菲特完全收购，成为伯克希尔·哈撒韦的重要组成部分。麦克法兰在这一过程中见证了所罗门从一家独立的华尔街投行转变为伯克希尔子公司的历史性转变，也见证了巴菲特独特的投资哲学和管理风格在公司治理中的实践。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1991年</strong>：所罗门兄弟国债丑闻爆发，作为高管参与危机应对</li><li><strong>1992年</strong>：协助公司完成整改，与巴菲特共同推进监管和解</li><li><strong>1997年</strong>：所罗门被伯克希尔完全收购，完成整合</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search?q=约翰·麦克法兰在1992年股东信中的原话">1992年：完整翻译|/01_letters/1992年/翻译</a></li></ul>',11)])])}const u=e(o,[["render",n]]);export{d as __pageData,u as default};
